// One shape for every booking, whichever door it came through.
// Cal door: the Cal.com BOOKING_CREATED webhook. Manual door: a JSON body already in this shape
// (email, firstName, lastName, domain, startTime, title, meetingUrl, notes, source, hostKeys[], clientRecId).
const sd=$getWorkflowStaticData('global');
sd.runStartedAt=$now.toMillis();
const FREEMAIL=new Set(['gmail.com','googlemail.com','yahoo.com','hotmail.com','outlook.com','live.com','icloud.com','me.com','aol.com','protonmail.com','proton.me','gmx.com','mail.com','walla.co.il','walla.com']);
const stripDomain=(u)=>String(u||'').trim().toLowerCase().replace(/^https?:\/\//,'').replace(/^www\./,'').split('/')[0].split('?')[0];
let cal=null, manual=null;
try{ cal=$('Cal Booking').first().json; }catch(e){}
try{ manual=$('Manual Booking').first().json; }catch(e){}
let out;
if(cal){
  const b=cal.body||{}; const p=b.payload||{};
  const ev=String(b.triggerEvent||'');
  if(ev!=='BOOKING_CREATED'){ return [{ json:{ _ignore:true, reason:'Cal.com event '+(ev||'?')+' is not a new booking'+(p.uid?' ('+p.uid+')':''), event:ev } }]; }
  const a=(p.attendees||[])[0]||{};
  const email=String(a.email||'').toLowerCase().trim();
  const nameParts=String(a.name||'').trim().split(/\s+/);
  const website=(p.responses&&p.responses.website&&p.responses.website.value)||'';
  const emailDomain=email.split('@')[1]||'';
  const domain=stripDomain(website)||(FREEMAIL.has(emailDomain)?'':emailDomain);
  const org=p.organizer||{};
  out={ source:'Cal.com', email, firstName:nameParts[0]||'', lastName:nameParts.slice(1).join(' '), fullName:String(a.name||'').trim(), domain,
    startTime:p.startTime||'', title:p.title||p.eventTypeTitle||'', meetingUrl:(p.videoCallData&&p.videoCallData.url)||p.location||'', bookingUid:p.uid||'',
    notes:(p.responses&&p.responses.notes&&p.responses.notes.value)||p.additionalNotes||'',
    hostKeys:[org.email, org.username, org.name, p.eventTypeTitle, p.type].map(x=>String(x||'').toLowerCase().trim()).filter(Boolean), clientRecId:'' };
} else if(manual){
  const b=manual.body||{};
  const email=String(b.email||'').toLowerCase().trim();
  const emailDomain=email.split('@')[1]||'';
  out={ source:String(b.source||'manual'), email, firstName:String(b.firstName||''), lastName:String(b.lastName||''), fullName:String(b.fullName||((b.firstName||'')+' '+(b.lastName||''))).trim(), domain:stripDomain(b.domain)||(FREEMAIL.has(emailDomain)?'':emailDomain),
    startTime:String(b.startTime||''), title:String(b.title||''), meetingUrl:String(b.meetingUrl||''), bookingUid:String(b.bookingUid||''), notes:String(b.notes||''),
    hostKeys:(Array.isArray(b.hostKeys)?b.hostKeys:[]).map(x=>String(x||'').toLowerCase().trim()).filter(Boolean), clientRecId:String(b.clientRecId||'') };
} else { return [{ json:{ _ignore:true, reason:'no trigger payload' } }]; }
if(!out.email) return [{ json:{ _ignore:true, reason:'booking without an attendee email' } }];
out._ignore=false;
return [{ json: out }];

// Which client does this booking belong to? Nothing hardcoded: the registry decides.
// 1. The manual door may name the client outright.
// 2. The booking's host keys (organizer email / username / event title) against each client's Booking Keys lines.
// 3. The attendee's domain against each client's own Email Domains: that is a client meeting, not a lead.
const n=$('Normalize Booking').first().json;
const clients=$input.all().map(it=>it.json).filter(r=>r&&r.id).map(r=>{ const f=r.fields||r; return { id:r.id, f }; });
const lines=(v)=>String(v||'').split('\n').map(s=>s.toLowerCase().trim()).filter(Boolean);
const pick=(c)=>{ const f=c.f; const name=String(f['Client']||''); return { clientRecId:c.id, clientName:name, clientSlug:name.toLowerCase().replace(/[^a-z0-9]/g,''), slackChannel:String(f['Slack Channel ID']||'').trim(), pvWorkspace:String(f['PlusVibe Workspace ID']||'').trim(), clayrootsBase:String(f['Clayroots Base ID']||'').trim(), dashboardPage:String(f['Dashboard Page ID']||'').trim(), isFlowroots:name.toLowerCase()==='flowroots' }; };
let hit=null, resolution='';
if(n.clientRecId){ hit=clients.find(c=>c.id===n.clientRecId)||null; resolution=hit?'named by the caller':''; }
if(!hit && n.hostKeys && n.hostKeys.length){ hit=clients.find(c=>lines(c.f['Booking Keys']).some(k=>n.hostKeys.includes(k)))||null; if(hit) resolution='host key matched Booking Keys'; }
let clientMeeting=false;
if(!hit && n.domain){ const own=clients.find(c=>lines(c.f['Email Domains']).includes(n.domain))||null; if(own){ hit=own; clientMeeting=true; resolution='attendee domain is the client\'s own domain'; } }
if(!hit) return [{ json:{ clientRecId:'', clientName:'', clientMeeting:false, resolution:'no client matched host keys '+JSON.stringify(n.hostKeys||[]) } }];
return [{ json: Object.assign(pick(hit), { clientMeeting, resolution }) }];

// Tier 2: not in the CRM. Is this a lead we sequenced? The client's PlusVibe workspace says.
const c=$('Resolve Client').first().json;
const r=$input.first().json||{};
const body=(r.body!==undefined)?r.body:r;
let lead=null;
if(body&&typeof body==='object'){ if(body._id||body.email) lead=body; else if(Array.isArray(body.leads)&&body.leads.length) lead=body.leads[0]; else if(body.lead&&typeof body.lead==='object') lead=body.lead; }
if(!c.pvWorkspace) return [{ json:{ ours:false, tier:'', why:'client has no PlusVibe workspace to check', campaign:'', companyName:'', title:'' } }];
if(!lead) return [{ json:{ ours:false, tier:'', why:'not a lead in the client\'s PlusVibe workspace', campaign:'', companyName:'', title:'' } }];
const campaign=String(lead.campaign_name||lead.campaign||'').trim();
return [{ json:{ ours:true, tier:'Sequenced', why:'in the client\'s PlusVibe workspace'+(campaign?', campaign '+campaign:''), campaign, companyName:String(lead.company_name||'').trim(), title:String(lead.job_title||'').trim(), pvLeadId:String(lead._id||'') } }];

// Tier 3: every table in the client's ClayRoots base that has a Domain column gets one search for the booker's domain.
const c=$('Resolve Client').first().json;
const n=$('Normalize Booking').first().json;
const r=$input.first().json||{};
const tables=Array.isArray(r.tables)?r.tables:[];
const domain=String(n.domain||'').toLowerCase().replace(/'/g,'');
if(!c.clayrootsBase||!domain||!tables.length) return [{ json:{ _empty:true, reason:!c.clayrootsBase?'client has no ClayRoots base':(!domain?'booker has no company domain (freemail)':'base has no tables') } }];
const out=[];
for(const t of tables){
  const hasDomain=(t.fields||[]).some(f=>f&&f.name==='Domain');
  if(!hasDomain) continue;
  const formula="LOWER({Domain})='"+domain+"'";
  out.push({ json:{ tableId:t.id, tableName:t.name, url:'https://api.airtable.com/v0/'+c.clayrootsBase+'/'+t.id+'?maxRecords=1&fields%5B%5D=Domain&filterByFormula='+encodeURIComponent(formula) } });
}
if(!out.length) return [{ json:{ _empty:true, reason:'no table with a Domain column in the client base' } }];
return out;

// Tier 3 verdict: the first table holding the booker's company domain makes the lead ours (Sourced).
const plan=$('Plan List Search').all().map(i=>i.json);
if(plan.length===1&&plan[0]._empty) return [{ json:{ ours:false, tier:'', why:plan[0].reason||'no lists to check', tableName:'', tablesChecked:0 } }];
const results=$input.all().map(i=>i.json);
let hit=null;
results.forEach((r,i)=>{ const recs=(r&&Array.isArray(r.records))?r.records:[]; if(!hit&&recs.length){ hit=plan[i]||{}; } });
if(hit) return [{ json:{ ours:true, tier:'Sourced', why:'company domain is on our list '+(hit.tableName||hit.tableId), tableName:hit.tableName||'', tablesChecked:plan.length } }];
return [{ json:{ ours:false, tier:'', why:'company domain is on none of the client\'s '+plan.length+' list table(s)', tableName:'', tablesChecked:plan.length } }];

// One attribution record for a booker who was not in the CRM, from whichever tier claimed them.
let seq=null, src=null;
try{ seq=$('Assess Lead').first().json; }catch(e){}
try{ src=$('Assess Lists').first().json; }catch(e){}
const a=(seq&&seq.ours)?seq:((src&&src.ours)?src:null);
if(!a) return [{ json:{ tier:'', why:'unattributed', campaign:'', companyName:'', title:'' } }];
return [{ json:{ tier:a.tier, why:a.why, campaign:a.campaign||'', companyName:a.companyName||'', title:a.title||'', tableName:a.tableName||'' } }];

let prospectId='', priorNotes='', priorThread='', priorBrief='', existed=false, tier='', why='';
try{ const f=$('Find Prospect').first().json; if(f&&f.id){ prospectId=f.id; const ff=f.fields||f; priorNotes=String(ff.contextNotes||''); priorThread=String(ff['Conversation Thread']||''); priorBrief=String(ff['Qualification Brief']||''); existed=true; tier='Replied'; why='already a prospect of this client (replied before)'; } }catch(e){}
if(!prospectId){ try{ prospectId=$('Create Prospect').first().json.id||''; }catch(e){} try{ const a=$('Attribution').first().json; tier=a.tier||''; why=a.why||''; }catch(e){} }
return [{ json:{ prospectId, priorNotes, priorThread:priorThread.slice(0,6000), priorBrief:priorBrief.slice(0,1500), existed, tier, why } }];

// The system prompt is the client's qualification-prompt KB row; the history is whatever the prospect already carries.
const c=$('Resolve Client').first().json;
const p=$('Resolve Prospect').first().json;
const n=$('Normalize Booking').first().json;
let kb='';
try{ const r=$input.first().json||{}; const f=r.fields||r; kb=String(f['Content']||'').replace(/\\([_*[\]`#|>~-])/g,'$1').trim(); }catch(e){}
const systemPrompt=kb||('You qualify inbound leads for '+c.clientName+', a B2B company. Decide whether the lead is a fit and return the structured JSON asked for.');
let title='', companyName='';
try{ const a=$('Attribution').first().json; title=a.title||''; companyName=a.companyName||''; }catch(e){}
const attributionLine=(p.tier==='Replied')?'They replied to our cold email earlier and are already in the CRM; now they booked.':(p.tier==='Sequenced')?('They never replied; they were in our cold email sequence ('+p.why+') and booked straight from it.'):(p.tier==='Sourced')?('They never replied and are not in the sequencer by this address; their company is on one of our lists for this client ('+p.why+'), so a colleague was emailed.'):'Attribution unknown.';
const history=[p.priorBrief?('Previous qualification: '+p.priorBrief):'', p.priorThread?('Conversation thread:\n'+p.priorThread):'', p.priorNotes?('Notes:\n'+p.priorNotes.slice(0,3000)):''].filter(Boolean).join('\n\n')||'(none)';
return [{ json:{ systemPrompt, kbFound:!!kb, title, companyName, attributionLine, history } }];

