const stripCite=(t)=>String(t||'').replace(/[-]/g,'').replace(/cite(turn\d+\w+?\d+)+/gi,'').replace(/turn\d+(?:view|search|news|image|video|product|ref)\d+/gi,'').replace(/cite/gi,'').replace(/ {2,}/g,' ').trim();
const stripEmoji=(t)=>String(t||'').replace(/:[a-z0-9_+-]+:/gi,'').replace(/[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}\u{2B00}-\u{2BFF}\u{2190}-\u{21FF}\u{2300}-\u{23FF}\u{FE0F}\u{200D}]/gu,'').replace(/ {2,}/g,' ').trim();
const q=($input.first().json||{}).output||{};
const n=$('Normalize Booking').first().json;
const p=$('Resolve Prospect').first().json;
const status=String(q.qualification_status||'');
const qualificationStatus=({strong:'Qualified',medium:'Needs Review',weak:'Needs Review',out_of_icp:'Disqualified'})[status]||'Needs Review';
const vlabel=({strong:'Qualified',medium:'Qualified (medium confidence)',weak:'Qualified (weak fit)',out_of_icp:'Not qualified'})[status]||'Needs review';
const vreason=stripEmoji(stripCite(q.verdict_reason||'')).slice(0,200);
const brief=stripCite(q.slack_brief_markdown||'').slice(0,2800);
const briefLines=(vlabel+(vreason?': '+vreason:'')+'\n\n'+stripEmoji(brief)).split('\n').map(s=>s.trim()).filter(Boolean);
const briefMd=briefLines.length?(['**'+briefLines[0]+'**',''].concat(briefLines.slice(1).map(l=>'- '+l))).join('\n'):'';
const when=(n.startTime||'').slice(0,16).replace('T',' ');
const line='Booked via '+n.source+' on '+$now.toFormat('yyyy-MM-dd')+': '+(n.title||'(untitled)')+' at '+(when||'?')+(n.meetingUrl?' | '+n.meetingUrl:'')+'. Attribution: '+(p.tier||'Unattributed')+(p.why?' ('+p.why+')':'')+'. Verdict: '+qualificationStatus+(vreason?' ('+vreason+')':'')+'.';
const contextNotes=((p.priorNotes||'').trim()?(p.priorNotes.trim()+'\n\n'):'')+line;
return [{ json:{ qualificationStatus, verdict:status, verdictReason:vreason, briefMd, brief, situation:stripCite(q.situation_summary||'').slice(0,200), recommended:stripCite(q.recommended_action||'').slice(0,300), timezone:String(q.timezone||''), companyName:String(q.company_name||''), contextNotes, attributionLine:line } }];

const n=$('Normalize Booking').first().json;
const c=$('Resolve Client').first().json;
const p=$('Resolve Prospect').first().json;
let v={}; try{ v=$('Flatten Verdict').first().json||{}; }catch(e){}
if(!c.slackChannel) return [{ json:{ post:false, channel:'', text:'' } }];
const when=n.startTime?new Date(n.startTime).toUTCString():'(time unknown)';
let url='';
if(p.prospectId&&c.dashboardPage){ try{ url='https://airtable.com/appQG6dK0FIOhTxOl/'+c.dashboardPage+'?detail='+Buffer.from(JSON.stringify({pageId:'pagU8C93nMn6vPMTM',rowId:p.prospectId}),'utf8').toString('base64').replace(/=+$/,''); }catch(e){} }
const esc=(s)=>String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const text=[':calendar: *Call booked* · '+esc(v.companyName||n.domain||n.fullName),
  '*Who:* '+esc(n.fullName||n.email)+' <'+esc(n.email)+'>'+(n.domain?' · '+esc(n.domain):''),
  '*When:* '+when, n.title?'*What:* '+esc(n.title):'', n.meetingUrl?'*Link:* '+n.meetingUrl:'',
  '*How we got here:* '+esc(p.tier||'Unattributed')+(p.why?' ('+esc(p.why)+')':''),
  v.qualificationStatus?'*Fit:* '+esc(v.qualificationStatus)+(v.verdictReason?' · '+esc(v.verdictReason):''):'',
  v.situation?'*What they want:* '+esc(v.situation):'',
  v.brief?'\n'+v.brief.slice(0,1500):'',
  url?'<'+url+'|Open in pipeline>':''
].filter(Boolean).join('\n');
return [{ json:{ post:true, channel:c.slackChannel, text } }];

const sd=$getWorkflowStaticData('global'); const rs=sd.runStartedAt||0;
let n={}; try{ n=$('Normalize Booking').first().json||{}; }catch(e){}
let c={}; try{ c=$('Resolve Client').first().json||{}; }catch(e){}
let p=null; try{ p=$('Resolve Prospect').first().json; }catch(e){}
let lists=null; try{ lists=$('Assess Lists').first().json; }catch(e){}
let seq=null; try{ seq=$('Assess Lead').first().json; }catch(e){}
let v=null; try{ v=$('Flatten Verdict').first().json; }catch(e){}
let qc=null; try{ qc=$('Qual Context').first().json; }catch(e){}
let meetingId=''; try{ meetingId=$('Create Meeting').first().json.id||''; }catch(e){}
let stamped=false; try{ stamped=!!($('Stamp Booked').first().json||{}).id; }catch(e){}
let posted=false; try{ const s=$('Post Booking Card').first().json||{}; posted=!!(s.ts||(s.message&&s.message.ts)||s.ok===true); }catch(e){}
const failed=[]; const skipped=[];
const who=(n.fullName||'')+' <'+(n.email||'')+'>'+(n.domain?' ('+n.domain+')':'');
const lines=['- **Source:** '+(n.source||'?')+(n.bookingUid?' ('+n.bookingUid+')':''), '- **Attendee:** '+who, '- **When:** '+(n.startTime||'?')+(n.title?' · '+n.title:'')];
let head='';
if(n._ignore){ head='Ignored'; skipped.push(n.reason||'not a booking'); }
else if(!c.clientRecId){ head='Unresolved client'; skipped.push(c.resolution||'no client matched'); }
else if(c.clientMeeting){ head='Client meeting, not a lead'; skipped.push(c.resolution); lines.push('- **Client:** '+c.clientName); }
else {
  lines.push('- **Client:** '+c.clientName+' ('+(c.resolution||'')+')');
  if(p&&p.prospectId){
    head=(p.tier==='Replied'?'Inbox lead booked':p.tier==='Sequenced'?'Sequenced lead booked (never replied)':p.tier==='Sourced'?'Sourced lead booked (company on our list)':'Lead booked');
    lines.push('- **Attribution:** '+(p.tier||'?')+' · '+(p.why||''));
    lines.push('- **Prospect:** '+(p.existed?'matched existing row':'created')+' ('+p.prospectId+')');
    lines.push('- **Qualification:** '+(v?(v.qualificationStatus+(v.verdictReason?' · '+v.verdictReason:'')+(qc&&!qc.kbFound?' (no qualification-prompt KB row for this client, generic rubric used)':'')):'NOT run'));
    if(!v) failed.push('qualification did not produce a verdict');
    lines.push('- **Stamped:** '+(stamped?'OutreachStatus = Scheduled Call, Call Booked At, QualificationStatus, Qualification Brief, contextNotes'+(c.isFlowroots?', PipelineStatus = Scheduled Call':''):'NOT stamped')); if(!stamped) failed.push('prospect not stamped');
    lines.push('- **Meeting:** '+(meetingId?'Meetings row created ('+meetingId+')':'NOT created')); if(!meetingId) failed.push('meeting row not created');
    if(c.slackChannel){ lines.push('- **Slack:** '+(posted?'card posted to '+c.slackChannel:'card NOT posted')); if(!posted) failed.push('slack card not posted'); }
  } else {
    head='Booking not attributed';
    skipped.push('not ours: '+(seq&&seq.why?seq.why:'')+(lists&&lists.why?'; '+lists.why:''));
    lines.push('- **Outcome:** no prospect, no meeting row; this booker was not generated by us');
  }
}
let desc='**'+head+': '+(n.fullName||n.email||'?')+'**\n\n'+lines.join('\n');
if(skipped.length) desc+='\n\n**Skipped ('+skipped.length+')**\n'+skipped.map(x=>'- '+x).join('\n');
if(failed.length) desc+='\n\n**FAILED ('+failed.length+')**\n'+failed.map(x=>'- '+x).join('\n');
const row={ 'Automation':'Handle New Booking', 'Status':failed.length?'Succeeded with errors':'Succeeded', 'Run at':$now.toISO(), 'Records In':1, 'Records Out':(p&&p.prospectId?1:0)+(meetingId?1:0), 'Errors':failed.length, 'Target':n.email||'', 'Trigger':'event', 'Execution ID':String($execution.id), 'Execution Link':'https://n8n.flowroots.com/workflow/'+$workflow.id+'/executions/'+$execution.id, 'Duration s':Math.round(($now.toMillis()-(rs||$now.toMillis()))/1000), 'Description':desc };
if(c.clientRecId) row['Client']=[c.clientRecId];
return [{ json: row }];
